    private bool signalC; // Sinalizando horário da operação de compra/venda
    private double RSI_curto; // Valor curto prazo do indicador RSI
    private double RSI_medio; // Valor médio termo do indicador RSI
    private double RSI_largo; // Valor longo prazo do indicador RSI

    // Construtor onde inicializamos nossas propriedades
    public TradeStrategy(bool initialSignalC, double shortTermRSIValue, double mediumTermRSIValue, double longTermRSIValue){
        signalC = initialSignalC;
        RSI_curto = shortTermRSIValue;
        RSI_medio = mediumTermRSIValue;
        RSI_largo = longTermRSIValue;
    }   

    /* Método responsável pela lógica principal */
    public void ExecuteTradingLogic(){
       if((!(RSI_curto > 50) && !(RSI_medio > 50)) || !signalC ){
           Console.WriteLine("Não realizar nenhuma ação.");
       } else{
          ExecuteBuyingOrSellingOperation();
      }
   }

   /* Realiza alguma função relacionada à execução das ordens*/
   private void ExecuteBuyingOrSellingOperation() {
     Console.WriteLine("Realizar Operação!");
   }
 }

